"""Small exact finite diagnostics; these are not universal mathematical proofs."""
from fractions import Fraction as F
from math import comb, inf
from pathlib import Path
import json

def main():
 counts={}
 counts['polynomial_degree_count']=0
 for n in range(1,7):
  for m in range(1,25):
   N=sum(comb(j+n-1,n-1) for j in range(m+1))
   W=sum(j*comb(j+n-1,n-1) for j in range(m+1))
   assert N==comb(m+n,n) and W==n*comb(m+n,n+1)
   assert F(W,m*N)==F(n,n+1)
   counts['polynomial_degree_count']+=1
 counts['signed_shift']=0
 for m in range(1,80):
  # chi(z^j) = -ceil(j/2), generated by z and z^2 both of weight -1.
  old=[F(-((j+1)//2)) for j in range(m+1)]
  for a in [F(-3,2),F(1,3),F(2)]:
   shifted=[old[j]+a*j for j in range(m+1)]
   assert sum(shifted)==sum(old)+a*sum(range(m+1))
   counts['signed_shift']+=1
 assert -F(-1)<-F(-1)-F(-1) # negating chi violates chi(z^2)>=2 chi(z)
 counts['root_examples']=0
 for degrees in [(F(1),F(2)),(F(2),F(3)),(F(3,2),F(7,3))]:
  c,C=min(degrees),max(degrees)
  for vx,vy in [(0,0),(3,0),(0,2),(inf,0),(0,inf)]:
   for lx in [F(-4),F(-1),F(0),F(2)]:
    for ly in [F(-3),F(0),F(3)]:
     tx=-inf if vx==inf else lx-vx
     ty=-inf if vy==inf else ly-vy
     u=max(tx,ty); r=max(tx/degrees[0],ty/degrees[1])
     orbit=max(tx-r*degrees[0],ty-r*degrees[1]);assert orbit==0
     if u<=0: assert u/c<=r<=u/C
     else: assert u/C<=r<=u/c
     counts['root_examples']+=1
 counts['negative_cutoff_inclusions']=0
 for m in range(1,65):
  W=lambda a,b,M:sum(-i-3*j for i in range(int(M/a)+1) for j in range(int(M/b)+1) if a*i+b*j<=M)
  assert W(1,1,m)<=W(1,2,m)<=W(1,1,F(m,2))
  counts['negative_cutoff_inclusions']+=1
 counts['rank_six_residue_examples']=0
 residues={(2*a+3*b)%6:(a,b) for a in range(3) for b in range(2)}
 assert len(residues)==6
 for a in range(20):
  for b in range(20):
   r,s=residues[(2*a+3*b)%6]
   assert a>=r and b>=s and (a-r)%3==0 and (b-s)%2==0
   counts['rank_six_residue_examples']+=1
 module=[]
 for m in [24,60,120]:
  pairs=[(a,b) for a in range(m//2+1) for b in range(m//3+1) if 2*a+3*b<=m]
  NR=len(pairs);WR=sum(-a-2*b for a,b in pairs)
  M=F(m,6);apairs=[(a,b) for a in range(int(M)+1) for b in range(int(M)+1) if a+b<=M]
  NA=len(apairs);WA=sum(-3*a-4*b for a,b in apairs)
  module.append({'cutoff':m,'N_R':NR,'W_R':WR,'six_N_A':6*NA,'six_W_A':6*WA,
                 'signed_mean':str(F(WR,m*NR)),'limit_predicted_by_proof':'-7/18',
                 'genuine_energy_predicted_by_proof':'-7/12'})
 counts['quadratic_binomial_bounds']=0
 for p in range(1,9):
  for A in [F(1,2),F(1),F(3)]:
   for tau in [F(1,4),F(1)]:
    for j in range(1,11):
     t=tau*F(j,10)
     assert (1+A*t)**p-1<=p*A*(1+A*tau)**(p-1)*t
     counts['quadratic_binomial_bounds']+=1
 out={'all_checks_pass':True,'counts':counts,'weighted_polynomial_module':module,
      'observation_scope':'Exhaustive only on the explicitly enumerated finite inputs. No check proves the cone energy identification, obstacle-volume equality, or uniform differentiation.'}
 Path('checks-output.json').write_text(json.dumps(out,indent=2)+'\n')
 print(json.dumps(out))

if __name__=='__main__':main()
